function ReceiptAccounting({line,masters,t}:Any){const d=line.data;const vat=d.country==='RO'&&(d.hasCompanyCui??d.documentType==='InvoiceWithCui');return <div className="receipt-accounting"><div><span>{d.country==='RO'?t('Furnizor din România','Romanian supplier'):t('Furnizor din străinătate','Foreign supplier')}</span>{d.country==='RO'&&<span>{vat?t('Cu CUI-ul companiei','Company VAT ID printed'):t('Fără CUI-ul companiei','Company VAT ID not printed')}</span>}{vat&&<span>{t('CUI furnizor','Supplier VAT ID')}: {d.cui}</span>}<span>{t('Total bon','Receipt total')}: {formatOriginal(d.amount)} {d.currency}</span></div>{vat&&<div className="table-wrap"><table><thead><tr><th>{t('Cotă TVA','VAT rate')}</th><th>{t('Bază','Base')}</th><th>{t('TVA plătit','VAT paid')}</th><th>{t('Total','Total')}</th></tr></thead><tbody>{Array.from(new Set<number>([0,11,21,...d.taxes.map((tax:Any)=>Number(JSON.parse(masters.find((m:Any)=>m.id===tax.rateId)?.json||'{}').rate||0))])).map(pct=>{const row=d.taxes.find((tax:Any)=>{const master=masters.find((m:Any)=>m.id===tax.rateId);return master&&Number(JSON.parse(master.json).rate)===pct;});return <tr key={pct}><td>{pct}%</td><td>{formatOriginal(row?.base||0)}</td><td>{formatOriginal(row?.vat||0)}</td><td>{formatOriginal(add(row?.base||'0',row?.vat||'0'))} {d.taxCurrency||'RON'}</td></tr>;})}</tbody></table></div>}</div>;}
