function BatchPanel({report,me,t,run,refresh}:Any){const[batches,B]=useState<Any[]>([]),[reference,R]=useState(''),[reason,Reason]=useState(''),[reversal,RV]=useState('');const load=()=>api('/finance/batches').then((xs:Any[])=>B(xs.filter(b=>b.reportId===report.id)));useEffect(()=>{if(me.roles.includes('Finance'))run(load);},[report.version]);return <div className="queue"><h3>{t('Exporturi salvate','Saved export batches')}</h3>{batches.map(b=><div className="batch" key={b.id}><strong>{t('Ciclul','Cycle')} {b.cycle} · {b.state}</strong><small>{b.id}</small><a className="text-button" href={'/api/batches/'+b.id+'/xlsx'}><Download size={15}/>{t('Descarcă XLSX','Download XLSX')}</a>{b.state==='Posted'&&me.roles.includes('FinanceReopen')&&<div className="form-grid"><Field name={t('Referință reversare ERP','ERP reversal reference')}><input value={reversal} onChange={e=>RV(e.target.value)}/></Field><Field name={t('Motiv redeschidere','Reopen reason')}><input value={reason} onChange={e=>Reason(e.target.value)}/></Field><button className="secondary danger" disabled={reason.length<3||reversal.length<3} onClick={()=>run(async()=>{await api('/finance/batches/'+b.id+'/reopen','POST',{version:report.version,reason,reversalReference:reversal});await refresh();await load();})}>{t('Redeschide după reversare ERP','Reopen after ERP reversal')}</button></div>}{b.state==='Exported'&&me.roles.includes('Finance')&&<div className="form-grid"><Field name={t('Referință postare ERP','ERP posting reference')}><input value={reference} onChange={e=>R(e.target.value)}/></Field><button className="primary" disabled={!reference} onClick={()=>run(async()=>{await api('/finance/batches/'+b.id+'/posted','POST',{version:report.version,reference});await refresh();await load();})}>{t('Confirmă postarea','Confirm posting')}</button>{me.roles.includes('FinanceReopen')&&<><Field name={t('Motiv anulare','Void reason')}><input value={reason} onChange={e=>Reason(e.target.value)}/></Field><button className="secondary danger" disabled={reason.length<3} onClick={()=>run(async()=>{await api('/finance/batches/'+b.id+'/void','POST',{version:report.version,reason});await refresh();await load();})}>{t('Anulează exportul','Void export')}</button></>}</div>}</div>)}{!batches.length&&<p className="muted">{t('Nu există exporturi încă.','No export batches yet.')}</p>}</div>;}
